export function posterUrl(clipId: string) {
  return `${EXERCISE_CATALOG.basePath}/p/${clipId}.webp`;
}

export function findClip(clipId: string) {
  return EXERCISE_CATALOG.clips.find((c) => c.id === clipId) ?? null;
}

